class KthLargest {
  constructor(k, nums) {
    this.k = k;
    this.sorted = [...nums].sort((a, b) => a - b);   // smallest first, sorted once
  }
  add(val) {
    let lo = 0, hi = this.sorted.length;     // binary search for where val belongs
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (this.sorted[mid] < val) lo = mid + 1; else hi = mid;
    }
    this.sorted.splice(lo, 0, val);          // insert: shifts up to n values
    return this.sorted[this.sorted.length - this.k];
  }
}

