class KthLargest {
    private final int k;
    private final List<Integer> sorted = new ArrayList<>();

    KthLargest(int k, int[] nums) {
        this.k = k;
        for (int x : nums) sorted.add(x);
        Collections.sort(sorted);                    // smallest first, sorted once
    }

    int add(int val) {
        int lo = 0, hi = sorted.size();              // binary search for where val belongs
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (sorted.get(mid) < val) lo = mid + 1; else hi = mid;
        }
        sorted.add(lo, val);                         // insert: shifts up to n values
        return sorted.get(sorted.size() - k);
    }
}

