import heapq

class KthLargest:
    def __init__(self, k, nums):
        self.k = k
        self.heap = []                       # a min-heap of the k largest so far
        for x in nums:
            self.add(x)

    def add(self, val):
        heapq.heappush(self.heap, val)
        if len(self.heap) > self.k:
            heapq.heappop(self.heap)         # drop the smallest: it left the top k
        return self.heap[0]                  # the smallest of the k largest = the kth largest

class KthLargest {
    private final int k;
    private final PriorityQueue<Integer> heap = new PriorityQueue<>();   // the k largest so far

    KthLargest(int k, int[] nums) {
        this.k = k;
        for (int x : nums) add(x);
    }

    int add(int val) {
        heap.offer(val);
        if (heap.size() > k) heap.poll();    // drop the smallest: it left the top k
        return heap.peek();                  // the smallest of the k largest = the kth largest
    }
}

